%% Figure 3 - Representativeness
%
% Generates Figure 3 from previously computed Representativeness results.
%
% Figure 3A:
%   Harmonic-wise mean Representativeness and stability ratio across
%   population sample sizes.
%
% Figure 3B:
%   Sample size dependence of Representativeness, between-subject
%   variability and subject-ranking stability.
%
% Figure 3C:
%   Harmonic-wise profiles of complementary Representativeness metrics
%   at N = 700.
%
% This script performs visualization only. All analytical quantities are
% generated by Run_Representativeness.m



%% Loading the required data

RepositoryDir = '/Users/bolton/Desktop/Paper2_Reproducibility';
DataDir = '/Users/bolton/Desktop/Paper2_Data';
ResultsDir = fullfile(RepositoryDir,'results');

addpath(genpath(fullfile(RepositoryDir,'src')));
addpath(genpath(fullfile(RepositoryDir,'external')));

load(fullfile(ResultsDir,'Representativeness_HarmonicSimilarityMatch_Results.mat'));



%% Definitions

Topology = "AllEdges";
Weights = "AllValues";

Nmax = 700;
R = 216;

AlphaVal = 0.3;


%% Color maps

% Heat maps
CM_Greens = cbrewer2('seq','Greens',1000,'linear');
CM_YlGn = cbrewer2('seq','YlGn',1000,'linear');

% Harmonic profiles
CM_Harmo = cbrewer2('div','PiYG',11,'linear');


%% Figure 3A - Harmonic-wise Representativeness

% Reference construction
T = RepresentativenessHarmonicDescriptives( ...
    RepresentativenessHarmonicDescriptives.Topology == Topology & ...
    RepresentativenessHarmonicDescriptives.Weights == Weights,:);

% Sample sizes and harmonic indices
NSamples = unique(T.N);
Harmonics = unique(T.Harmonic);

% Initializes heat maps
HeatMap_HWSM = nan(numel(Harmonics),numel(NSamples));
HeatMap_StabilityRatio = nan(numel(Harmonics),numel(NSamples));


for ns = 1:numel(NSamples)

    % Current sample size
    TN = T(T.N == NSamples(ns),:);
    TN = sortrows(TN,'Harmonic');

    % One observation is expected per harmonic
    assert(height(TN) == numel(Harmonics));

    % Mean harmonic-wise Representativeness
    HeatMap_HWSM(:,ns) = ...
        TN.E_Realization_Mean_Subject;

    % Stability ratio
    HeatMap_StabilityRatio(:,ns) = ...
        TN.StabilityRatio;

end


% -------------------------------------------------------------------------
% Mean harmonic-wise Representativeness
% -------------------------------------------------------------------------

figure;

imagesc(NSamples,Harmonics,HeatMap_HWSM);

colormap(CM_Greens);
clim([0 1]);

xlabel('Population sample size');
ylabel('Harmonic index');

set(gca, ...
    'YDir','normal', ...
    'TickDir','out', ...
    'Box','off');


% -------------------------------------------------------------------------
% Stability ratio
% -------------------------------------------------------------------------

figure;

imagesc(NSamples,Harmonics,HeatMap_StabilityRatio);

colormap(CM_YlGn);
clim([0 1]);

xlabel('Population sample size');
ylabel('Harmonic index');

set(gca, ...
    'YDir','normal', ...
    'TickDir','out', ...
    'Box','off');


%% Figure 3B - Sample size dependence of Representativeness

TVar = RepresentativenessSubjectVariability( ...
    RepresentativenessSubjectVariability.Topology == Topology & ...
    RepresentativenessSubjectVariability.Weights == Weights & ...
    RepresentativenessSubjectVariability.Metric == ...
        "Median_HarmonicSimilarityMatch",:);

TVar = sortrows(TVar,'N');


% -------------------------------------------------------------------------
% Mean Representativeness across subjects
% -------------------------------------------------------------------------

figure;
hold on;

% Mean +/- SD across subjects
fill( ...
    [TVar.N' fliplr(TVar.N')], ...
    [(TVar.Mean_Subject_E_Realization - ...
      TVar.SD_Subject_E_Realization)' ...
     fliplr((TVar.Mean_Subject_E_Realization + ...
      TVar.SD_Subject_E_Realization)')], ...
    CM_Greens(700,:), ...
    'EdgeColor','none', ...
    'FaceAlpha',AlphaVal);

% Mean across subjects
plot( ...
    TVar.N, ...
    TVar.Mean_Subject_E_Realization, ...
    'LineWidth',1, ...
    'Color',CM_Greens(700,:), ...
    'Marker','o', ...
    'MarkerFaceColor',CM_Greens(700,:), ...
    'MarkerSize',6, ...
    'MarkerEdgeColor','k');

xlim([5 700]);

xlabel('Population sample size');
ylabel('Required subspace window');

box off;

set(gca, ...
    'TickDir','out', ...
    'FontSize',12);


% -------------------------------------------------------------------------
% Between-subject variability
% -------------------------------------------------------------------------

figure;
hold on;

% 2.5th-97.5th percentile interval across population realizations for
% realization-wise between-subject variability
fill( ...
    [TVar.N' fliplr(TVar.N')], ...
    [TVar.P025_Realization_SD_Subject' ...
     fliplr(TVar.P975_Realization_SD_Subject')], ...
    CM_YlGn(450,:), ...
    'EdgeColor','none', ...
    'FaceAlpha',AlphaVal);

% Typical between-subject variability within individual population
% realizations: E_r[SD_s(X)]
plot( ...
    TVar.N, ...
    TVar.E_Realization_SD_Subject, ...
    'LineWidth',1, ...
    'Color',CM_YlGn(450,:), ...
    'Marker','o', ...
    'MarkerFaceColor',CM_YlGn(450,:), ...
    'MarkerSize',6, ...
    'MarkerEdgeColor','k');

% Persistent between-subject variability after averaging across
% population realizations: SD_s[E_r(X)]
plot( ...
    TVar.N, ...
    TVar.SD_Subject_E_Realization, ...
    'LineWidth',1, ...
    'Color',CM_YlGn(300,:), ...
    'Marker','o', ...
    'MarkerFaceColor',CM_YlGn(300,:), ...
    'MarkerSize',6, ...
    'MarkerEdgeColor','k');

xlim([5 700]);

xlabel('Population sample size');
ylabel('Between-subject variability');

box off;

set(gca, ...
    'TickDir','out', ...
    'FontSize',12);


% -------------------------------------------------------------------------
% Stability of subject ordering
% -------------------------------------------------------------------------

TRank = sortrows(RepresentativenessSubjectRanking,'N');

figure;
hold on;

plot( ...
    TRank.N, ...
    TRank.Rho_N700, ...
    'LineWidth',1, ...
    'Color',CM_Greens(900,:), ...
    'Marker','o', ...
    'MarkerFaceColor',CM_Greens(900,:), ...
    'MarkerSize',6, ...
    'MarkerEdgeColor','k');

xlim([5 700]);
ylim([0.8 1]);

xlabel('Population sample size');
ylabel('Subject-ranking similarity with N = 700');

box off;

set(gca, ...
    'TickDir','out', ...
    'FontSize',12);


%% Figure 3C - Harmonic-wise Representativeness profiles at N = 700

figure;
hold on;

AxesHarmo = gca;


% -------------------------------------------------------------------------
% Matched harmonic similarity
% -------------------------------------------------------------------------

load(fullfile(ResultsDir,...
    'Representativeness_HarmonicSimilarityMatch_Results.mat'),...
    'RepresentativenessHarmonicDescriptives');

T = RepresentativenessHarmonicDescriptives( ...
    RepresentativenessHarmonicDescriptives.Topology == Topology & ...
    RepresentativenessHarmonicDescriptives.Weights == Weights & ...
    RepresentativenessHarmonicDescriptives.N == Nmax,:);

T = sortrows(T,'Harmonic');

% Similarity is inverted so that larger values consistently represent
% greater population-to-individual mismatch
Y = 1 - T.Mean_Subject_E_Realization;
YSD = T.SD_Subject_E_Realization;

fill( ...
    AxesHarmo, ...
    [T.Harmonic' fliplr(T.Harmonic')], ...
    [(Y + YSD)' fliplr((Y - YSD)')], ...
    CM_Harmo(8,:), ...
    'EdgeColor','none', ...
    'FaceAlpha',AlphaVal + 0.3);

plot( ...
    AxesHarmo, ...
    T.Harmonic, ...
    Y, ...
    'LineWidth',1, ...
    'Color',CM_Harmo(8,:), ...
    'Marker','none');


% -------------------------------------------------------------------------
% Leakage entropy
% -------------------------------------------------------------------------

load(fullfile(ResultsDir,...
    'Representativeness_LeakageEntropy_Results.mat'),...
    'RepresentativenessHarmonicDescriptives');

T = RepresentativenessHarmonicDescriptives( ...
    RepresentativenessHarmonicDescriptives.Topology == Topology & ...
    RepresentativenessHarmonicDescriptives.Weights == Weights & ...
    RepresentativenessHarmonicDescriptives.N == Nmax,:);

T = sortrows(T,'Harmonic');

% Normalized by maximum entropy
Y = T.Mean_Subject_E_Realization ./ log(R);
YSD = T.SD_Subject_E_Realization ./ log(R);

fill( ...
    AxesHarmo, ...
    [T.Harmonic' fliplr(T.Harmonic')], ...
    [(Y + YSD)' fliplr((Y - YSD)')], ...
    CM_Harmo(9,:), ...
    'EdgeColor','none', ...
    'FaceAlpha',AlphaVal + 0.1);

plot( ...
    AxesHarmo, ...
    T.Harmonic, ...
    Y, ...
    'LineWidth',1, ...
    'Color',CM_Harmo(9,:), ...
    'Marker','none');


% -------------------------------------------------------------------------
% Bandwidth index
% -------------------------------------------------------------------------

load(fullfile(ResultsDir,...
    'Representativeness_BandwidthIndex_Results.mat'),...
    'RepresentativenessHarmonicDescriptives');

T = RepresentativenessHarmonicDescriptives( ...
    RepresentativenessHarmonicDescriptives.Topology == Topology & ...
    RepresentativenessHarmonicDescriptives.Weights == Weights & ...
    RepresentativenessHarmonicDescriptives.N == Nmax,:);

T = sortrows(T,'Harmonic');

% Normalized by maximum possible harmonic-index displacement
Y = T.Mean_Subject_E_Realization ./ (R-1);
YSD = T.SD_Subject_E_Realization ./ (R-1);

fill( ...
    AxesHarmo, ...
    [T.Harmonic' fliplr(T.Harmonic')], ...
    [(Y + YSD)' fliplr((Y - YSD)')], ...
    CM_Harmo(10,:), ...
    'EdgeColor','none', ...
    'FaceAlpha',AlphaVal + 0.1);

plot( ...
    AxesHarmo, ...
    T.Harmonic, ...
    Y, ...
    'LineWidth',1, ...
    'Color',CM_Harmo(10,:), ...
    'Marker','none');


% -------------------------------------------------------------------------
% Required subspace-similarity windows
% -------------------------------------------------------------------------

load(fullfile(ResultsDir,...
    'Representativeness_SubspaceSimilarityRequiredWindows_Results.mat'),...
    'RepresentativenessHarmonicDescriptives');

T = RepresentativenessHarmonicDescriptives( ...
    RepresentativenessHarmonicDescriptives.Topology == Topology & ...
    RepresentativenessHarmonicDescriptives.Weights == Weights & ...
    RepresentativenessHarmonicDescriptives.N == Nmax,:);

T = sortrows(T,'Harmonic');

% Normalized by maximum possible harmonic-index displacement
Y = T.Mean_Subject_E_Realization ./ (R-1);
YSD = T.SD_Subject_E_Realization ./ (R-1);

fill( ...
    AxesHarmo, ...
    [T.Harmonic' fliplr(T.Harmonic')], ...
    [(Y + YSD)' fliplr((Y - YSD)')], ...
    CM_Harmo(11,:), ...
    'EdgeColor','none', ...
    'FaceAlpha',AlphaVal);

plot( ...
    AxesHarmo, ...
    T.Harmonic, ...
    Y, ...
    'LineWidth',1, ...
    'Color',CM_Harmo(11,:), ...
    'Marker','none');


% -------------------------------------------------------------------------
% Axes
% -------------------------------------------------------------------------

xlim([1 R]);
ylim([0 0.8]);

xlabel('Harmonic index');
ylabel('Normalized mismatch');

box off;

set(gca, ...
    'TickDir','out', ...
    'FontSize',12);